SPEC = {'kind': 'extrusion', 'center': [-0.22608478999999998, -0.39233827499999996, -0.0047118349999999976], 'basis': [[0.0, -0.0, 1.0], [0.0, 1.0, 0.0], [-1.0, 0.0, 0.0]], 'axis': [1.0, 0.0, 0.0], 'zmin': -0.042013650000000013, 'zmax': 0.042013649999999986, 'profiles': [{'outer': [[-0.201414565, -0.08005336500000004], [-0.163400975, -0.09913861500000004], [-0.167688635, -0.10760930500000004], [-0.205649925, -0.08852404500000005]], 'holes': []}, {'outer': [[-0.243140625, -0.05887657500000004], [-0.205179335, -0.07790953500000003], [-0.209414675, -0.08638024500000002], [-0.247428285, -0.06734728500000003]], 'holes': []}, {'outer': [[-0.268343595, -0.021961035000000018], [-0.245023015, -0.057464775000000023], [-0.252918555, -0.06269362500000003], [-0.276239125, -0.027137575000000025]], 'holes': []}, {'outer': [[-0.278173775, 5.499999994329485e-08], [-0.277912345, 0.019503594999999985], [-0.268395865, 0.019399044999999948], [-0.268709565, 5.499999994329485e-08], [-0.268395865, -0.019398895000000027], [-0.277912345, -0.019503475000000048]], 'holes': []}, {'outer': [[-0.252918525, 0.06269374499999997], [-0.245022985, 0.05746489499999996], [-0.268343595, 0.021961154999999954], [-0.276239125, 0.02713769499999996]], 'holes': []}, {'outer': [[-0.209414625, 0.08638033499999997], [-0.205179285, 0.07790961499999993], [-0.243140575, 0.05887669499999998], [-0.247428235, 0.06734740499999997]], 'holes': []}, {'outer': [[-0.16768856499999998, 0.10760936499999996], [-0.163400915, 0.09913867499999995], [-0.201414525, 0.08010572499999996], [-0.205649885, 0.08857643499999995]], 'holes': []}, {'outer': [[-0.021229065, -0.10766163500000003], [-0.021229065, -0.09819746500000004], [0.021281315000000002, -0.09819746500000004], [0.021281315000000002, -0.10766163500000003]], 'holes': []}, {'outer': [[-0.024784675, -0.09819746500000004], [-0.024784675, -0.10766163500000003], [-0.06729505499999999, -0.10766160500000005], [-0.06729505499999999, -0.09819746500000004]], 'holes': []}, {'outer': [[-0.113099615, -0.09819743500000006], [-0.070589235, -0.09819746500000004], [-0.070589235, -0.10766160500000005], [-0.113099615, -0.10766160500000005]], 'holes': []}, {'outer': [[-0.117805565, -0.10766160500000005], [-0.160263685, -0.10766160500000005], [-0.160263675, -0.09819740500000002], [-0.117805565, -0.09819743500000006]], 'holes': []}, {'outer': [[-0.021229005, 0.09819742499999995], [-0.021229005, 0.10766163499999998], [0.021281375, 0.10766160499999994], [0.021281375, 0.09819742499999995]], 'holes': []}, {'outer': [[-0.024784614999999996, 0.10766163499999998], [-0.024784614999999996, 0.09819742499999995], [-0.067294995, 0.09819745499999993], [-0.067294995, 0.10766163499999998]], 'holes': []}, {'outer': [[-0.070589175, 0.09819745499999993], [-0.113099555, 0.09819745499999993], [-0.113099555, 0.10766163499999998], [-0.070589165, 0.10766163499999998]], 'holes': []}, {'outer': [[-0.11780550499999999, 0.10766166499999996], [-0.11780550499999999, 0.09819745499999993], [-0.160263615, 0.09819748499999997], [-0.160263615, 0.10766166499999996]], 'holes': []}, {'outer': [[0.117805535, -0.09819749500000002], [0.16031594500000002, -0.09819752500000006], [0.160315935, -0.10766166500000002], [0.117805535, -0.10766166500000002]], 'holes': []}, {'outer': [[0.07058919500000001, -0.09819746500000004], [0.113099595, -0.09819749500000002], [0.113099595, -0.10766166500000002], [0.07058919500000001, -0.10766166500000002]], 'holes': []}, {'outer': [[0.024784635000000003, -0.09819746500000004], [0.067295035, -0.09819746500000004], [0.067295035, -0.10766166500000002], [0.024784635000000003, -0.10766166500000002]], 'holes': []}, {'outer': [[0.11780560500000001, 0.10766157499999995], [0.160316005, 0.10766157499999995], [0.160316005, 0.09819736499999998], [0.117805595, 0.09819739499999997]], 'holes': []}, {'outer': [[0.113099665, 0.10766157499999995], [0.11309965500000001, 0.09819739499999997], [0.070589255, 0.09819739499999997], [0.070589265, 0.10766160499999994]], 'holes': []}, {'outer': [[0.024784695000000002, 0.10766160499999994], [0.06729510500000001, 0.10766160499999994], [0.067295095, 0.09819739499999997], [0.024784695000000002, 0.09819742499999995]], 'holes': []}, {'outer': [[0.205649915, -0.08852416500000004], [0.167688575, -0.10760939500000005], [0.163453255, -0.09913867500000006], [0.201414525, -0.08005347500000004]], 'holes': []}, {'outer': [[0.24742826499999998, -0.06734740500000003], [0.209414665, -0.08638036500000001], [0.205179325, -0.07790964500000003], [0.243192915, -0.05887672500000002]], 'holes': []}, {'outer': [[0.252970845, -0.06269377500000006], [0.245023025, -0.05746495500000004], [0.268343595, -0.02196118500000005], [0.276291405, -0.02713775500000004]], 'holes': []}, {'outer': [[0.268709635, -9.500000003326292e-08], [0.268448205, 0.019398864999999932], [0.277912355, 0.019503444999999953], [0.278173775, -9.500000003326292e-08], [0.277912355, -0.019503655000000064], [0.268448205, -0.01939904500000006]], 'holes': []}, {'outer': [[0.276291405, 0.027137514999999945], [0.268343595, 0.021960974999999938], [0.245023055, 0.057464744999999984], [0.252970845, 0.06269359499999994]], 'holes': []}, {'outer': [[0.24742829500000002, 0.06734725499999994], [0.24319295500000002, 0.05887654499999995], [0.205179365, 0.07790949499999994], [0.209414705, 0.08638021499999998]], 'holes': []}, {'outer': [[0.205649955, 0.08857631499999996], [0.201414575, 0.08010560499999997], [0.16345331500000002, 0.09913855499999996], [0.167688655, 0.10760927499999995]], 'holes': []}], 'simplify_tolerance': 0.00011126951000000002, 'sketch_entity_count': 116}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
